B.am=s([],t.zr)
B.Xb=s(["Th..Thank you, Mateo. I..I owe you my life...","The words grow distant as exhaustion pulls you back into darkness."],t.s)
B.Oy=new A.cv("Close your eyes","intro_pass_out_to_spanish_home",!0,!1)
B.YY=s([B.Oy],t.u)
B.Pl=new A.ci(B.am,B.Xb,null,null,null,B.YY)
B.Xg=s([B.Pl],t.J)
B.OH=new A.cO("Player",B.Xg)
B.XI=s(["Then what should I call you?"],t.s)
B.Ot=new A.cv("Choose your name","intro_choose_player_name",!0,!1)
B.V7=s([B.Ot],t.u)
B.Pg=new A.ci(B.am,B.XI,null,null,null,B.V7)
B.UB=s([B.Pg],t.J)
B.OI=new A.cO("Concerned Stranger",B.UB)
B.Vw=s(["Welcome, captain. Your ship has good bones, but there is always room for finer work.","Would you like to order work on your ship?"],t.s)
B.Oq=new A.cv("View ship upgrades","open_ship_upgrade_menu",!1,!0)
B.XM=s([B.Oq,B.fY],t.u)
B.P6=new A.ci(B.am,B.Vw,null,null,null,B.XM)
B.Xw=s([B.P6],t.J)
B.OJ=new A.cO("Shipwright",B.Xw)
B.Wv=s(["The player stirs, violently coughing up seawater. There is a distinct taste of iron admist the saltiness. The chill on your flesh is contrasted by the burning in your side."],t.s)
B.Or=new A.cv("Next","intro_show_stranger",!0,!1)
B.Zb=s([B.Or],t.u)
B.P9=new A.ci(B.am,B.Wv,null,null,null,B.Zb)
B.Wn=s([B.P9],t.J)
B.OK=new A.cO("Narrator",B.Wn)
B.WV=s(["I...I...I don't know... I..."],t.s)
B.Om=new A.cv("Try to Remember","intro_show_british_officer",!0,!1)
B.Zj=s([B.Om],t.u)
B.Pc=new A.ci(B.am,B.WV,null,null,null,B.Zj)
B.VK=s([B.Pc],t.J)
B.OL=new A.cO("Player",B.VK)
B.YH=s(["I... I cannot remember."],t.s)
B.On=new A.cv("Continue","intro_ask_player_name",!0,!1)
B.WD=s([B.On],t.u)
B.Pv=new A.ci(B.am,B.YH,null,null,null,B.WD)
B.W0=s([B.Pv],t.J)
B.OM=new A.cO("Player",B.W0)
B.Zo=s(["Nothing... apart from a face.","A young man with dark hair and cold eyes. He wore a naval coat finer than any officer's, with a golden lion at his collar.","He looked at me as though he knew me. Then everything went dark."],t.s)
B.Oc=new A.cv("Watch Mateo's reaction","intro_mateo_recognizes_prince",!0,!1)
B.Z2=s([B.Oc],t.u)
B.Pe=new A.ci(B.am,B.Zo,null,null,null,B.Z2)
B.Yv=s([B.Pe],t.J)
B.ON=new A.cO("Player",B.Yv)
B.VH=s(["That sounds like the Prince of Britain.","The British Navy has been cracking down hard on piracy. If you crossed paths with the prince himself, they may have taken you for a pirate.","But the crown calls everyone a criminal when it suits them. The government is corrupt, and poverty has spread across the nation while the powerful line their own pockets.","Many people down on their luck have turned to piracy simply to make ends meet. For some, it is the only way left to put food on the table."],t.s)
B.dP=s([],t.u)
B.Ps=new A.ci(B.am,B.VH,null,null,null,B.dP)
B.V9=s([B.Ps],t.J)
B.OO=new A.cO("Mateo",B.V9)
B.YD=s(["Welcome to the cafe, captain. You look like you could use something strong after your voyage.","Would you like to browse today's menu of consumables?"],t.s)
B.Of=new A.cv("Browse menu","open_spanish_cafe_menu",!0,!1)
B.V8=s([B.Of,B.fY],t.u)
B.Pk=new A.ci(B.am,B.YD,null,null,null,B.V8)
B.Z3=s([B.Pk],t.J)
B.OP=new A.cO("Barista",B.Z3)
B.YV=s(["Hey\u2014stay with me. Can you hear me?","Who are you?"],t.s)
B.Ob=new A.cv("Try to remember","intro_cannot_remember_name",!0,!1)
B.Xj=s([B.Ob],t.u)
B.Pb=new A.ci(B.am,B.YV,null,null,null,B.Xj)
B.YN=s([B.Pb],t.J)
B.OQ=new A.cO("Concerned Stranger",B.YN)
B.Z4=s(["The fortress harbor opens, and the Royal Navy sails out to meet you.","Gilded warships spread across the channel beneath British flags, forming a wall between your fleet and the island.","Neither armada turns away."],t.s)
B.Pn=new A.ci(B.am,B.Z4,null,null,null,B.dP)
B.YX=s([B.Pn],t.J)
B.OR=new A.cO("Narrator",B.YX)
B.WB=s(["The cave trembles as something immense stirs beneath the black water.","A forest of tentacles rises from the depths, and a furious eye fixes upon your crew.","You were a fool to come here."],t.s)
B.Ox=new A.cv("Face the Kraken","start_kraken_fight",!0,!1)
B.Wy=s([B.Ox],t.u)
B.Pw=new A.ci(B.am,B.WB,null,null,null,B.Wy)
B.WE=s([B.Pw],t.J)
B.OS=new A.cO("The Kraken",B.WE)
B.WG=s(["You close your eyes. The room falls away.","His face emerges from the darkness, framed by drifting smoke: the same cold stare, the same golden insignia."],t.s)
B.Ow=new A.cv("Open your eyes","intro_describe_remembered_face",!0,!1)
B.Wg=s([B.Ow],t.u)
